from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Log_cmd(EmssimCommand):
    def __init__(self, method="log", timeout=60, rpc_connection_name='localRPC'):
        super(Log_cmd, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Log_cmd, self).on_new_data(**data)
        if ("status" in data):
            self._ret["status"] = data["status"]
